from langflow.custom import Component
from langflow.io import HandleInput, Output
from langflow.schema.message import Message


class CustomComponent(Component):
    display_name = "RAG Prompt Builder"
    description = "Ground the user's question in retrieved StockSage news before the LLM answers."
    icon = "filter"
    name = "StockSageRagPrompt"

    MAX_ARTICLES = 8

    inputs = [
        HandleInput(
            name="question",
            display_name="Question",
            input_types=["Message"],
            info="The user's chat message.",
        ),
        HandleInput(
            name="context",
            display_name="Retrieved News",
            input_types=["Data", "DataFrame", "Table"],
            info="Vector-search results from the Astra DB news store.",
        ),
    ]
    outputs = [
        Output(display_name="Prompt", name="prompt", method="build_prompt"),
    ]

    def _records(self) -> list:
        data = self.context
        if data is None:
            return []
        if hasattr(data, "to_dict"):
            try:
                return data.to_dict(orient="records")
            except Exception:  # noqa: BLE001
                pass
        if isinstance(data, list):
            return [getattr(x, "data", x) for x in data]
        inner = getattr(data, "data", None)
        if isinstance(inner, list):
            return [getattr(x, "data", x) for x in inner]
        if isinstance(inner, dict):
            return [inner]
        return []

    def _question_text(self) -> str:
        q = self.question
        if isinstance(q, str):
            return q.strip()
        return (getattr(q, "text", "") or "").strip()

    def build_prompt(self) -> Message:
        blocks: list[str] = []
        for record in self._records()[: self.MAX_ARTICLES]:
            if not isinstance(record, dict):
                continue
            meta = record.get("metadata") if isinstance(record.get("metadata"), dict) else record
            ticker = meta.get("ticker") or meta.get("ticket") or "?"
            title = meta.get("title") or "(untitled)"
            source = meta.get("source") or "unknown source"
            date = meta.get("publication_date") or "n/a"
            sentiment = meta.get("sentiment") or "Neutral"
            body = (
                meta.get("key_observations")
                or meta.get("description")
                or record.get("page_content")
                or ""
            )
            body = body.strip() if isinstance(body, str) else ""
            blocks.append(
                f"[{ticker}] {title}\nSource: {source} | Date: {date} | Sentiment: {sentiment}\n{body}"
            )

        context = "\n\n---\n\n".join(b for b in blocks if b)
        question = self._question_text() or "Give me a brief overview of the market."

        if context:
            text = (
                "Use the NEWS CONTEXT below to answer the QUESTION. The context is AI-analysed "
                "market news retrieved for relevance. Ground every claim in it, cite the source "
                "and sentiment where useful, and never invent prices or figures. If the context "
                "does not cover the question, say so briefly, then answer generally.\n\n"
                f"NEWS CONTEXT:\n{context}\n\n"
                f"QUESTION: {question}"
            )
        else:
            text = (
                "There is no stored news relevant to this question. Answer the QUESTION concisely "
                "from general knowledge and make clear it is not based on StockSage's latest "
                f"analysed news.\n\nQUESTION: {question}"
            )

        self.status = f"{len(blocks)} context block(s)"
        return Message(text=text)
